INSERT INTO `<table_name>`(`id`, `name`, `profile`, `detail`, `cover`, `icons`, `type`, `store_id`, `brand`, `column_type`, `order_by`, `state`, `is_hot`, `old_price`, `price`, `hehuoren_price`, `xiaofeijin_price`, `create_by`, `create_time`, `update_by`, `update_time`, `verify_state`, `verify_by`, `verify_time`, `verify_remark`, `dept_id`, `is_delete`, `is_integral`, `group_buy`, `group_buy_num`, `group_buy_rate`, `is_flash_kill`, `flash_kill_rate`, `sales_volume`, `use_num`, `discount_rate`, `feature`, `stock`, `direct_rate`) VALUES (151, '新能源灶', NULL, '<p>新能源家用灶具 vs 液化气灶 核心优势对比</p><p>&nbsp;</p><p>对比维度 新能源家用灶具 液化气灶&nbsp;</p><p>核心能源 无需煤气/电/液化气，依赖创新新能源技术（如生物质能、新型燃料等），摆脱传统能源依赖 需持续采购液化气，受气源供应、价格波动影响大&nbsp;</p><p>安全性 安全防爆设计，无燃气泄漏、爆炸风险，无明火隐患，使用场景更广泛（如厨房、阳台等） 存在液化气泄漏、爆炸、回火风险，明火使用需严格通风，受限场景多&nbsp;</p><p>使用成本 节能效率高，无燃料采购成本，仅需少量维护费用，长期使用省钱优势显著 需定期支付液化气采购费，气瓶押金、运输费叠加，长期使用成本偏高&nbsp;</p><p>便利性 无需更换气瓶、接线，开机即可使用，操作简单（适配老年人、普通家庭），无续航焦虑 需频繁更换气瓶，搬运笨重，气瓶存储占用空间，断气后无法即时使用&nbsp;</p><p>环保性 无废气排放（如一氧化碳、二氧化硫），无油烟污染，符合绿色家居、环保政策 燃烧产生废气、油烟，污染环境，长期使用影响室内空气质量&nbsp;</p><p>维护难度 结构简单，故障率低，维护周期长，无需专业人员频繁检修 需定期检查气瓶阀门、管道密封性，灶具易积油垢，维护频率高&nbsp;</p><p>&nbsp;</p><p>核心亮点总结</p><p>&nbsp;</p><p>新能源家用灶具的核心优势集中在 “零能源成本”“极致安全”“终身省钱” 三大维度，既解决了液化气灶的安全隐患和使用痛点，又契合当前环保政策和家庭降本需求，尤其适合西北等气源运输不便、对安全要求高的区域推广</p><p><br/></p>', '/profile/upload/2025/11/20/909e0c0ef0a24a458995b1cf14900078_20251120174454A273.jpg', '/profile/upload/2025/11/20/c4c0bf0fab17466cb69a102d647c5fe7_20251120174526A274.jpg,/profile/upload/2025/11/20/ab6adcdafd0540859dd99a65472280cf_20251120174536A275.png', NULL, 52, NULL, 0, 99, 1, 0, NULL, 1000.00, NULL, 0.00, 61, '2025-11-20 17:47:34', 61, '2025-12-06 10:51:08', 1, 61, '2025-12-06 10:51:03', '', 3, 0, 0, 0, 0, NULL, 0, NULL, NULL, 1, 0.3000, NULL, 1, 0.00);
